"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["3417"],{538494(n){n.exports=JSON.parse('{"id":7850,"title":"\u5B66\u672F","description":"\u4F5C\u4E3A\u4E00\u540DXX\u9886\u57DF\u7684\u7814\u7A76\u8005\uFF0C\u6211\u5E0C\u671B\u60A8\u80FD\u534F\u52A9\u6211\u9AD8\u6548\u9605\u8BFB\u548C\u603B\u7ED3\u5B66\u672F\u6587\u732E\u3002\u8BF7\u9488\u5BF9\u6211\u63D0\u4F9B\u7684\u8BBA\u6587\uFF0C\u4E25\u683C\u6309\u7167\u4EE5\u4E0B\u6846\u67B6\u8FDB\u884C\u68B3\u7406\u4E0E\u89E3\u6790\uFF1A\\n1.\u5305\u62EC\uFF1A\u4F5C\u8005\u3001\u53D1\u8868\u5E74\u4EFD\u3001\u8BBA\u6587\u6807\u9898\u3001\u671F\u520A/\u4F1A\u8BAE\u540D\u79F0\u3001\u5377\u53F7\u3001\u671F\u53F7\u3001\u8D77\u6B62\u9875\u7801\u3001DOI\u53F7\u3002\\n2.\u6E05\u6670\u9610\u8FF0\u672C\u7814\u7A76\u65E8\u5728\u89E3\u51B3\u7684\u6838\u5FC3\u79D1\u5B66\u95EE\u9898\u6216\u6280\u672F\u74F6\u9888\u3002\\n3.\u660E\u786E\u5217\u51FA\u4F5C\u8005\u63D0\u51FA\u7684\u6838\u5FC3\u7814\u7A76\u5047\u8BBE\u6216\u7406\u8BBA\u6784\u60F3\u3002\\n4.\u7814\u7A76\u8BBE\u8BA1\uFF1A\u6982\u8FF0\u6574\u4F53\u7814\u7A76\u601D\u8DEF\uFF08\u5982\uFF1A\u7406\u8BBA\u63A8\u5BFC\u3001\u4EFF\u771F\u6A21\u62DF\u3001\u5B9E\u9A8C\u9A8C\u8BC1\u3001\u6848\u4F8B\u7814\u7A76\u7B49\uFF09\u3002\\n5.\u6570\u636E/\u6837\u672C\u6765\u6E90\uFF1A\u8BF4\u660E\u6570\u636E\u83B7\u53D6\u65B9\u5F0F\u3001\u6837\u672C\u89C4\u6A21\u3001\u9009\u62E9\u6807\u51C6\u4E0E\u7279\u5F81\u3002\\n6.\u65B9\u6CD5\u4E0E\u6280\u672F\uFF1A\u8BE6\u8FF0\u6240\u4F7F\u7528\u7684\u5173\u952E\u6280\u672F\u3001\u7B97\u6CD5\u3001\u6A21\u578B\u3001\u5B9E\u9A8C\u5E73\u53F0\u3001\u8BD5\u5242\u6750\u6599\u6216\u8F6F\u4EF6\u5DE5\u5177\u3002\\n7.\u5206\u6790\u6D41\u7A0B\uFF1A\u5206\u6B65\u8BF4\u660E\u5B9E\u9A8C\u6B65\u9AA4\u3001\u4EFF\u771F\u6D41\u7A0B\u6216\u7406\u8BBA\u63A8\u5BFC\u7684\u5173\u952E\u73AF\u8282\u3002\\n8.\u6570\u636E\u5206\u6790\uFF1A\u8BF4\u660E\u6240\u91C7\u7528\u7684\u7EDF\u8BA1\u65B9\u6CD5\u3001\u6709\u6548\u6027\u9A8C\u8BC1\u624B\u6BB5\u6216\u6027\u80FD\u8BC4\u4EF7\u6307\u6807\u3002\\n9.\u6838\u5FC3\u53D1\u73B0\uFF1A\u63D0\u70BC\u7814\u7A76\u4E2D\u6700\u91CD\u8981\u3001\u6700\u521B\u65B0\u7684\u79D1\u5B66\u53D1\u73B0\u6216\u89C2\u6D4B\u73B0\u8C61\u3002\\n10.\u5B9E\u9A8C\u7ED3\u679C\uFF1A\u603B\u7ED3\u5173\u952E\u7684\u5B9A\u91CF\u7ED3\u679C\uFF08\u5982\uFF1A\u6027\u80FD\u6307\u6807\u3001\u7EDF\u8BA1\u663E\u8457\u6027\uFF09\u548C\u5B9A\u6027\u7ED3\u8BBA\u3002\\n11.\u8F85\u52A9\u7ED3\u679C\uFF1A\u7B80\u8FF0\u5176\u4ED6\u652F\u6301\u6027\u7684\u6B21\u8981\u7ED3\u679C\u3002\\n12.\u5F52\u7EB3\u4F5C\u8005\u57FA\u4E8E\u8BC1\u636E\u5F97\u51FA\u7684\u6700\u7EC8\u7ED3\u8BBA\u3002\\n13.\u8BC4\u4EF7\u672C\u7814\u7A76\u5728\u7406\u8BBA\u521B\u65B0\u3001\u6280\u672F\u7A81\u7834\u3001\u65B9\u6CD5\u6539\u8FDB\u6216\u5E94\u7528\u62D3\u5C55\u65B9\u9762\u5BF9XX\u9886\u57DF\u7684\u5177\u4F53\u8D21\u732E\u3002\\n14.\u5206\u6790\u8BE5\u5DE5\u4F5C\u4E0E\u6211\u7684\u7814\u7A76\u4E3B\u9898\u6216\u7EFC\u8FF0\u65B9\u5411\u7684\u6838\u5FC3\u5173\u8054\u3002\\n15.\u6307\u51FA\u5176\u503C\u5F97\u5728\u6211\u7684\u7EFC\u8FF0\u4E2D\u91CD\u70B9\u8BA8\u8BBA\u7684\u4EAE\u70B9\uFF08\u5982\uFF1A\u5F00\u521B\u6027\u3001\u4E89\u8BAE\u6027\u3001\u5C40\u9650\u6027\u3001\u672A\u6765\u542F\u793A\uFF09\u3002\\n16.\u5217\u51FA\u6587\u4E2D\u6240\u6709Figure\u548CTable\u7684\u7F16\u53F7\u3001\u6807\u9898\u53CA\u5176\u6240\u5C55\u793A\u7684\u6838\u5FC3\u5185\u5BB9\u6982\u8FF0\uFF0C\u65B9\u4FBF\u5FEB\u901F\u5B9A\u4F4D\u548C\u5F15\u7528\u5173\u952E\u8BC1\u636E\u3002\\n17.\u8BC4\u4EF7\uFF1A\u60A8\u5BF9\u8BE5\u7814\u7A76\u7684\u65B9\u6CD5\u4E25\u8C28\u6027\u3001\u903B\u8F91\u5B8C\u5907\u6027\u548C\u7ED3\u8BBA\u53EF\u9760\u6027\u7684\u4E2A\u4EBA\u8BC4\u4EF7\u3002\\n18.\u7591\u95EE\uFF1A\u9605\u8BFB\u4E2D\u4EA7\u751F\u7684\u7591\u95EE\u6216\u8BA4\u4E3A\u5176\u5B58\u5728\u7684\u4E0D\u8DB3\u4E4B\u5904\u3002\\n19.\u542F\u53D1\uFF1A\u8BE5\u7814\u7A76\u4E3A\u60A8\u5E26\u6765\u7684\u65B0\u601D\u8DEF\u3001\u65B0\u60F3\u6CD5\u6216\u672A\u6765\u53EF\u63A2\u7D22\u7684\u65B9\u5411\u3002\\n20.\u5217\u51FA\u6587\u4E2D\u5F15\u7528\u76841-2\u7BC7\u6700\u5177\u4EE3\u8868\u6027\u7684\u53C2\u8003\u6587\u732E\uFF08\u683C\u5F0F\uFF1A\u4F5C\u8005\uFF0C\u5E74\u4EFD\uFF0C\u6807\u9898\uFF0C\u671F\u520A\uFF0C\u5377\u671F\uFF0C\u9875\u7801\uFF09\uFF0C\u65B9\u4FBF\u6211\u8FFD\u6EAF\u91CD\u8981\u5B66\u672F\u6E0A\u6E90\u3002","owner":"","upvotes":30,"downvotes":1,"upvoteDifference":29,"updatedAt":"2026-06-22T09:15:02.156Z"}')}}]);